nextflow_process {

    name "Test Process BWAMEME_MEM"
    script "../main.nf"
    process "BWAMEME_MEM"

    tag "modules"
    tag "modules_nfcore"
    tag "bwameme"
    tag "bwameme/mem"
    tag "bwameme/index"
    config "./nextflow.config"

    setup {
        run("BWAMEME_INDEX") {
            script "../../index/main.nf"
            config "./nextflow.config"
            process {
                """
                input[0] = Channel.of([
                    [:], // meta map
                    [file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]
                ])
                """
            }
        }
    }

    test("sarscov2 - fastq, index, fasta, false") {

        when {
            params {
                module_args2 = ""
                module_args3 = ""
            }

            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:true ], // meta map
                    [file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)]
                ])
                input[1] = BWAMEME_INDEX.out.index
                input[2] = Channel.of([[:], [file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]])
                input[3] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    bam(process.out.output[0][1]).getHeaderMD5(),
                    bam(process.out.output[0][1]).getReadsMD5(),
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }

    }

    test("sarscov2 - fastq, index, fasta, true") {

        when {
            params {
                module_args2 = "-m 2048M"
                module_args3 = "-@ 4"
            }

            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:true ], // meta map
                    [file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)]
                ])
                input[1] = BWAMEME_INDEX.out.index
                input[2] = Channel.of([[:], [file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]])
                input[3] = true
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    bam(process.out.output[0][1]).getHeaderMD5(),
                    bam(process.out.output[0][1]).getReadsMD5(),
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }

    }

    test("sarscov2 - [fastq1, fastq2], index, fasta, false") {

        when {
            params {
                module_args2 = ""
                module_args3 = ""
            }

            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                input[1] = BWAMEME_INDEX.out.index
                input[2] = Channel.of([[:], [file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]])
                input[3] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    bam(process.out.output[0][1]).getHeaderMD5(),
                    bam(process.out.output[0][1]).getReadsMD5(),
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }

    }

    test("sarscov2 - [fastq1, fastq2], index, fasta, true") {

        when {
            params {
                module_args2 = "-m 2048M"
                module_args3 = "-@ 4"
            }

            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                input[1] = BWAMEME_INDEX.out.index
                input[2] = Channel.of([[:], [file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]])
                input[3] = true
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    bam(process.out.output[0][1]).getHeaderMD5(),
                    bam(process.out.output[0][1]).getReadsMD5(),
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }

    }

    test("sarscov2 - [fastq1, fastq2], index, fasta, true - stub") {

        options "-stub"

        when {
            params {
                module_args2 = "-m 2048M"
                module_args3 = "-@ 4"
            }

            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                input[1] = BWAMEME_INDEX.out.index
                input[2] = Channel.of([[:], [file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]])
                input[3] = true
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }
}

